add_action( 'init', 'perfectpixel_long_description_in_summary_setup' );
add_filter( 'woocommerce_product_tabs', 'perfectpixel_long_description_hide_tab', 98 );

function perfectpixel_long_description_in_summary_setup() {
	remove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_excerpt', 20 );
	add_action( 'woocommerce_single_product_summary', 'perfectpixel_long_description_in_summary', 20 );
}

function perfectpixel_long_description_in_summary() {
	echo '<div class="woocommerce-product-details__short-description perfectpixel-long-description">';
	the_content();
	echo '</div>';
}

function perfectpixel_long_description_hide_tab( $tabs ) {
	if ( 'yes' === '{{hide_description_tab}}' ) {
		unset( $tabs['description'] );
	}
	return $tabs;
}
